import {NextResponse} from "next/server";import {z} from "zod";import {getCurrentUser} from "@/lib/auth";import {connectMongoose} from "@/lib/db";import {VendorProfileModel} from "@/models/VendorProfile";const schema=z.object({displayName:z.string().trim().min(2).max(100),businessName:z.string().trim().max(120).optional(),phoneNumber:z.string().trim().min(7).max(30),state:z.string().trim().min(2).max(60),city:z.string().trim().min(2).max(60),description:z.string().trim().max(1000).optional()});export async function POST(r:Request){const user=await getCurrentUser();if(!user)return NextResponse.redirect(new URL("/login?next=/become-a-vendor",r.url));const f=Object.fromEntries(await r.formData()),p=schema.safeParse(f);if(!p.success)return NextResponse.json({error:"Invalid application"},{status:422});await connectMongoose();await VendorProfileModel.updateOne({userId:user.id},{$setOnInsert:{userId:user.id,status:"PENDING"},$set:p.data},{upsert:true});return NextResponse.redirect(new URL("/vendor?application=submitted",r.url),303)}
